package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("ಸುಬ್ಬಹುನ್ ಕುದ್ದುಸ್ (ರುಕು ಮತ್ತು ಸುಜೂದ್)", "(ಅಲ್ಲಾಹ್) ಅತ್ಯಂತ ಮಹಿಮೆ, ಅತ್ಯಂತ ಪವಿತ್ರ, ದೇವತೆಗಳು ಮತ್ತು ಆತ್ಮದ (ಜಿಬ್ರಿಲ್) ಒಡೆಯ.", "ರುಕು ಮತ್ತು ಸುಜೂದ್ನಲ್ಲಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಇದನ್ನು ರುಕು ಮತ್ತು ಸುಜೂದ್ ಭಾಷೆಗಳಲ್ಲಿ ಪಠಿಸಿದರು."),
        "dua_sujood_dhanbi_kullah" to DuaText("ಸುಜೂದ್ನಲ್ಲಿಃ ನನ್ನ ಎಲ್ಲಾ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸು.", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಎಲ್ಲಾ ಪಾಪಗಳನ್ನು-ಸಣ್ಣ ಮತ್ತು ದೊಡ್ಡ, ಮೊದಲ ಮತ್ತು ಕೊನೆಯ, ತೆರೆದ ಮತ್ತು ಗುಪ್ತವಾದವುಗಳನ್ನು ನನಗೆ ಕ್ಷಮಿಸು.", "ಸುಜೂದ್ನಲ್ಲಿ.", "ಪ್ರಾಸ್ಟ್ರೇಶನ್ ಎಂದರೆ ದುಆಗಳಿಗೆ ಉತ್ತರಿಸುವ ಸ್ಥಳವಾಗಿದೆ."),
        "dua_sujood_ridaka" to DuaText("ನಿಮ್ಮ ಸಂತೋಷದಲ್ಲಿ ಆಶ್ರಯ", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಕೋಪದಿಂದ ನಿನ್ನ ಸಂತೋಷದಲ್ಲಿ, ನಿನ್ನ ಶಿಕ್ಷೆಯಿಂದ ನಿನ್ನ ಕ್ಷಮೆಗಾಗಿ ನಾನು ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ ಮತ್ತು ನಿನ್ನಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ. ನಾನು ನಿನ್ನನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಸ್ತುತಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ನೀನು ನಿನ್ನನ್ನು ಸ್ತುತಿಸಿದಂತೆಯೇ ಇದ್ದೀಯ.", "ಸುಜೂದ್ನಲ್ಲಿ-ಆಯಿಶಾ (ರ.) ಅವರು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಮಾತನ್ನು ಕೇಳಿದರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಸುಜೂದ್ ದುಆ."),
        "dua_tashahhud" to DuaText("ತಾಶಹುದ್ (ಅಟ್-ತಾಹಿಯಾತ್)", "ಎಲ್ಲಾ ಮೌಖಿಕ, ದೈಹಿಕ ಮತ್ತು ಆರ್ಥಿಕ ಪೂಜೆಗಳು ಅಲ್ಲಾಹನಿಗಾಗಿವೆ. ಓ ಪ್ರವಾದಿ, ನಿಮ್ಮ ಮೇಲೆ ಶಾಂತಿ ಇರಲಿ, ಮತ್ತು ಅಲ್ಲಾಹ್ನ ಕರುಣೆ ಮತ್ತು ಅವನ ಆಶೀರ್ವಾದಗಳು. ನಮ್ಮ ಮೇಲೆ ಮತ್ತು ಅಲ್ಲಾಹ್ನ ಸದ್ಗುಣಶೀಲ ಸೇವಕರ ಮೇಲೆ ಶಾಂತಿ ಇರಲಿ. ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಪೂಜಿಸುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ ಎಂದು ನಾನು ಸಾಕ್ಷಿಯಾಗುತ್ತೇನೆ ಮತ್ತು ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವನ ಸೇವಕ ಮತ್ತು ಸಂದೇಶವಾಹಕರಾಗಿದ್ದಾರೆ ಎಂದು ನಾನು ಸಾಕ್ಷಿಯಾಗುತ್ತೇನೆ.", "ಪ್ರತಿ ಸಭೆಯಲ್ಲಿಯೂ-ಅಬ್ದುಲ್ಲಾ ಇಬ್ನ್ ಮಸೂದ್ (ರ. ಅ.) (ಹನಾಫಿ ಪದ್ಧತಿ) ವಿವರಿಸಿದ್ದಾನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಇದನ್ನು ಕುರಾನ್ನ ಸೂರಾದಂತೆ ಕಲಿಸಿದರು."),
        "dua_sajdah_tilawah" to DuaText("ಪಠಣದ ಸಜ್ದಾಹ್", "ನನ್ನ ಮುಖವು ಅದನ್ನು ಸೃಷ್ಟಿಸಿದವನಿಗೆ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡಿದೆ ಮತ್ತು ಅವನ ಶಕ್ತಿ ಮತ್ತು ಶಕ್ತಿಯಿಂದ ಅದರ ಶ್ರವಣ ಮತ್ತು ದೃಷ್ಟಿಯನ್ನು ಹೊರತಂದಿದೆ.", "ಪಠಣದಲ್ಲಿ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ರಾತ್ರಿ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರದಲ್ಲಿ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_after_witr" to DuaText("ವಿಟ್ರ್ ನಂತರ", "ಪರಮಪವಿತ್ರನಾದ ರಾಜನಿಗೆ ಮಹಿಮೆ ಇರಲಿ.", "ವಿದರ್ನ ಸಲಾಂ ನಂತರ ಮೂರು ಬಾರಿ, ಮೂರನೇ ಬಾರಿಗೆ ಧ್ವನಿಯನ್ನು ಎತ್ತಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ವಿದರ್ ನಂತರ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_tahajjud_nur" to DuaText("ತಹಜ್ಜುದಿನ ಆರಂಭಿಕ ಪ್ರಾರ್ಥನೆ", "ಓ ಅಲ್ಲಾಹನೇ, ಸ್ತುತಿಯು ನಿನಗೆ ಸೇರಿದ್ದು; ನೀನು ಆಕಾಶಗಳ, ಭೂಮಿಯ ಮತ್ತು ಅವುಗಳೊಳಗಿನ ಎಲ್ಲದರ ಪಾಲಕನಾಗಿದ್ದೀ. ಸ್ತುತಿಯು ನಿನಗೆ ಸೇರಿದ್ದು. ನೀನು ಆಕಾಶಗಳ, ಭೂಮಿಯ ಮತ್ತು ಅವುಗಳೊಳಗಿನ ಎಲ್ಲದರ ಬೆಳಕು. ಸ್ತುತಿಯು ನಿನಗೆ ಸೇರಿದ್ದು. ನೀನು ಸತ್ಯ, ನಿನ್ನ ವಾಗ್ದಾನವು ಸತ್ಯ, ನಿನ್ನೊಂದಿಗೆ ಭೇಟಿಯಾಗುವುದು ಸತ್ಯ, ನಿನ್ನ ಮಾತು ಸತ್ಯ, ಸ್ವರ್ಗವು ಸತ್ಯ, ನರಕವು ಸತ್ಯ, ಪ್ರವಾದಿಗಳು ಸತ್ಯ, ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಸತ್ಯ ಮತ್ತು ಆ ಸಮಯವು ಸತ್ಯ.", "ರಾತ್ರಿ ಪ್ರಾರ್ಥನೆಯನ್ನು (ತಹಜ್ಜುದ) (ದುಆದ ಆರಂಭಿಕ ಭಾಗ) ಪ್ರಾರಂಭಿಸುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ತಹಜ್ಜುದ್ಗಾಗಿ ಎದ್ದ ಮೇಲೆ ಇದನ್ನು ಪಠಿಸಿದರು (ಪೂರ್ಣ ದುಆ ಅಲ್-ಬುಖಾರೀಯಲ್ಲಿದೆ)."),
        "dua_rabba_jibrail" to DuaText("ವಿವಾದಾತ್ಮಕ ವಿಷಯಗಳಲ್ಲಿ ನನಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಿ", "ಓ ಅಲ್ಲಾಹನೇ, ಜಿಬ್ರಿಲ್ನ ಒಡೆಯನೇ, ಮೀಕೈಲ್ ಮತ್ತು ಇಸ್ರಾಫಿಲ್ನ ಒಡೆಯನೇ, ಆಕಾಶಗಳ ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಕರ್ತನೇ, ಅದೃಶ್ಯ ಮತ್ತು ದೃಷ್ಟಿಗೋಚರಗಳ ಅರಿವುಳ್ಳವನೇ! ನಿನ್ನ ಸೇವಕರ ನಡುವೆ ಅವರು ಯಾವ ವಿಷಯದಲ್ಲಿ ಭಿನ್ನಾಭಿಪ್ರಾಯ ಹೊಂದಿದ್ದರು ಎಂಬುದರ ಬಗ್ಗೆ ನೀನು ತೀರ್ಪು ನೀಡುತ್ತೀ. ನಿನ್ನ ಅನುಮತಿಯೊಂದಿಗೆ ಭಿನ್ನಾಭಿಪ್ರಾಯಗಳಿರುವ ಸತ್ಯದ ಕಡೆಗೆ ನನ್ನನ್ನು ಮಾರ್ಗದರ್ಶನ ಮಾಡು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಯಾರಿಗೆ ಬೇಕಾದರೋ ಅವರಿಗೆ ನೇರವಾದ ಮಾರ್ಗವನ್ನು ತೋರಿಸುತ್ತೀ.", "ತಹಜ್ಜುದ್ನ ಆರಂಭದಲ್ಲಿ-ಭಿನ್ನಾಭಿಪ್ರಾಯದ ನಡುವೆ ಸತ್ಯಕ್ಕೆ ಮಾರ್ಗದರ್ಶನಕ್ಕಾಗಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ದುಆದೊಂದಿಗೆ ತಮ್ಮ ರಾತ್ರಿ ಪ್ರಾರ್ಥನೆಯನ್ನು ಪ್ರಾರಂಭಿಸಿದರು."),
        "dua_going_to_mosque_nur" to DuaText("ಮಸೀದಿಗೆ ಹೋಗುವುದು (ಬೆಳಕಿನ ದುವಾ)", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಹೃದಯದಲ್ಲಿ ಬೆಳಕನ್ನು, ನನ್ನ ಕಣ್ಣುಗಳಲ್ಲಿ ಬೆಳಕನ್ನು, ನನ್ನ ಕಿವಿಗಳಲ್ಲಿ ಬೆಳಕನ್ನು, ನನ್ನ ಬಲಭಾಗದಲ್ಲಿ ಬೆಳಕನ್ನು, ನನ್ನ ಎಡಭಾಗದಲ್ಲಿ ಬೆಳಕನ್ನು, ನನ್ನ ಮೇಲೆ ಬೆಳಕನ್ನು, ನನ್ನ ಕೆಳಗೆ ಬೆಳಕನ್ನು, ನನ್ನ ಮುಂದೆ ಬೆಳಕನ್ನು, ನನ್ನ ಹಿಂದೆ ಬೆಳಕನ್ನು ಇರಿಸು ಮತ್ತು ನನಗೆ ಬೆಳಕನ್ನು ಮಾಡಿಕೊಡು.", "ಫಜ಼್ರ್ಗಾಗಿ ಮಸೀದಿಗೆ ಹೋಗುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರಾರ್ಥನೆಗಾಗಿ ಹೊರಗೆ ಹೋಗುವಾಗ ಇದನ್ನು ಪಠಿಸಿದರು."),
        "dua_waswasa_salah" to DuaText("ವಾಸ್ವಾಸಾ ಸಲಾಹ್ ಸಮಯದಲ್ಲಿ (ಖಿನ್ಜಾಬ್)", "ನಾನು ಶಾಪಗ್ರಸ್ತರಾದ ಸೈತಾನ್ನಿಂದ ಅಲ್ಲಾಹನ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಪ್ರಾರ್ಥನೆಯ ಸಮಯದಲ್ಲಿ ಸೈತಾನನ ಪಿಸುಗುಟ್ಟುವಿಕೆಗಳು ಬಂದಾಗ, ಆಶ್ರಯವನ್ನು ಪಡೆಯಿರಿ ಮತ್ತು ಎಡಕ್ಕೆ ಮೂರು ಬಾರಿ ಲಘುವಾಗಿ ಉಗುಳಿ.", "ಉಸ್ಮಾನ್ ಇಬ್ನ್ ಅಬಿಲ್-ಅಸ್ (ರ.) ಇದನ್ನು ಮಾಡಿದನು ಮತ್ತು ಪಿಸುಗುಟ್ಟುವುದು ದೂರವಾಯಿತು."),
        "dua_alimal_ghayb" to DuaText("ಕಾಣದ ಸಂಗತಿಗಳ ಅರಿವು", "ಓ ಅಲ್ಲಾಹನೇ, ಅದೃಶ್ಯ ಮತ್ತು ದೃಷ್ಟಿಗೋಚರವನ್ನು ಬಲ್ಲವನೇ, ಆಕಾಶಗಳ ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಕರ್ತನೇ, ಎಲ್ಲಾ ವಸ್ತುಗಳ ಒಡೆಯನೇ ಮತ್ತು ಅಧಿಪತಿ! ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ ಎಂದು ನಾನು ಸಾಕ್ಷಿಯಾಗಿ ಹೇಳುತ್ತೇನೆ. ನನ್ನ ಸ್ವಂತ ದುಷ್ಟತನದಿಂದ ಮತ್ತು ಸೈತಾನ ಮತ್ತು ಅವನ ದುಷ್ಟತನದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಬೆಳಿಗ್ಗೆ, ಸಂಜೆ ಮತ್ತು ಮಲಗುವ ಮೊದಲು-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಇದನ್ನು ಅಬು ಬಕರ್ (ರ.) ಅವರಿಗೆ ಕಲಿಸಿದರು.", "ಸ್ವಯಂ ಮತ್ತು ಶೈತಾನ್ನ ದುಷ್ಟತನದಿಂದ ರಕ್ಷಣೆ."),
        "dua_fitratil_islam" to DuaText("ಇಸ್ಲಾಂನ ಫಿತ್ರಾದ ಮೇಲೆ", "ನಾವು ಇಸ್ಲಾಂನ ಫಿತ್ರಾದಂದು, ಪ್ರಾಮಾಣಿಕತೆಯ ಮಾತಿನ ಮೇಲೆ, ನಮ್ಮ ಪ್ರವಾದಿ ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರ ಧರ್ಮದ ಮೇಲೆ ಮತ್ತು ನಮ್ಮ ತಂದೆ ಇಬ್ರಾಹಿಂ (ಎ. ಎಸ್) ಅವರ ದಾರಿಯಲ್ಲಿ ಬೆಳಿಗ್ಗೆ ಪ್ರವೇಶಿಸಿದೆವು, ಅವರು ನೇರವಾದ ಮತ್ತು ಮುಸ್ಲಿಮರಾಗಿದ್ದರು ಮತ್ತು ಬಹುದೇವತಾವಾದಿಗಳಲ್ಲ.", "ಬೆಳಗಿನ ಜಾವ.", "ಪ್ರತಿದಿನ ಬೆಳಿಗ್ಗೆ ಒಬ್ಬರ ನಂಬಿಕೆಯನ್ನು ನವೀಕರಿಸಿ."),
        "dua_amsayna_fitrah" to DuaText("ಇಸ್ಲಾಂನ ಫಿತ್ರಾದ ಸಂಜೆ", "ನಾವು ಇಸ್ಲಾಂನ ಫಿತ್ರಾದ ಸಂಜೆ, ಪ್ರಾಮಾಣಿಕತೆಯ ಮಾತಿನ ಮೇಲೆ, ನಮ್ಮ ಪ್ರವಾದಿ ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರ ಧರ್ಮದ ಮೇಲೆ ಮತ್ತು ನಮ್ಮ ತಂದೆ ಇಬ್ರಾಹಿಂ (ಎ. ಎಸ್) ಅವರ ದಾರಿಯಲ್ಲಿ ಪ್ರವೇಶಿಸಿದೆವು, ಅವರು ನೇರವಾದ ಮತ್ತು ಮುಸ್ಲಿಮರಾಗಿದ್ದರು ಮತ್ತು ಬಹುದೇವತಾವಾದಿಗಳಲ್ಲ.", "ಸಂಜೆ.", "ಪ್ರತಿ ಸಂಜೆ ಒಬ್ಬರ ನಂಬಿಕೆಯನ್ನು ನವೀಕರಿಸುವುದು."),
        "dua_tahleel_10_fajr" to DuaText("ಫಜರ್ ಮತ್ತು ಮಗ್ರಿಬ್ ನಂತರ ಹತ್ತು ತಹ್ಲೀಲ್", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಇದೆ ಮತ್ತು ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಇದೆ. ಅವನು ಜೀವವನ್ನು ನೀಡುತ್ತಾನೆ ಮತ್ತು ಮರಣವನ್ನು ಉಂಟುಮಾಡುತ್ತಾನೆ ಮತ್ತು ಅವನು ಎಲ್ಲದರ ಮೇಲೆ ಅಧಿಕಾರವನ್ನು ಹೊಂದಿದ್ದಾನೆ.", "ಫಜರ್ (ಮತ್ತು ಮಗ್ರಿಬ್) ನಂತರ ಹತ್ತು ಬಾರಿ, ನಿಮ್ಮ ಕುಳಿತುಕೊಳ್ಳುವ ಅಥವಾ ಮಾತನಾಡುವ ಮೊದಲು.", "ಹತ್ತು ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳು, ಹತ್ತು ಪಾಪಗಳು ಅಳಿಸಿಹೋಗಿವೆ, ಹತ್ತು ಸ್ಥಾನಗಳನ್ನು ಹೆಚ್ಚಿಸಲಾಗಿದೆ ಮತ್ತು ದಿನವಿಡೀ ಸೈತಾನ್ನಿಂದ ರಕ್ಷಣೆ ಇದೆ."),
        "dua_la_hawla_kanz" to DuaText("ಎ ಟ್ರೆಷರ್ ಆಫ್ ಜನ್ನಾ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ಯಾವುದೇ ಶಕ್ತಿ ಮತ್ತು ಶಕ್ತಿ ಇಲ್ಲ.", "ಸಾಮಾನ್ಯವಾಗಿ, ಎಲ್ಲಾ ಸಮಯದಲ್ಲೂ.", "ಇದು ಸ್ವರ್ಗದ ಸಂಪತ್ತುಗಳಲ್ಲಿ ಒಂದಾಗಿದೆ."),
        "dua_four_beloved_words" to DuaText("ಅತ್ಯಂತ ಪ್ರೀತಿಯ ನಾಲ್ಕು ಪದಗಳು", "ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ, ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ, ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಪೂಜಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ, ಮತ್ತು ಅಲ್ಲಾಹನು ಶ್ರೇಷ್ಠನು.", "ಅಲ್ಲಾಹನಿಗೆ ಅತ್ಯಂತ ಪ್ರಿಯವಾದ ಪದಗಳು.", "ಅವರು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರಿಗೆ ಸೂರ್ಯನು ಉದಯಿಸುವ ಎಲ್ಲದಕ್ಕಿಂತ ಹೆಚ್ಚು ಪ್ರಿಯವಾದವರು."),
        "dua_two_light_words" to DuaText("ಎರಡು ಪದಗಳು ನಾಲಿಗೆಯ ಮೇಲೆ ಬೆಳಕು", "ಮಹಿಮೆ ಅಲ್ಲಾಹನಿಗಿರಲಿ ಮತ್ತು ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅವನದೇ; ಮಹಿಮೆ ಮಹಿಮೆಯುಳ್ಳ ಅಲ್ಲಾಹನಿಗಿರಲಿ.", "ನಾಲಿಗೆಯ ಮೇಲೆ ಬೆಳಕು, ಮಾಪಕದ ಮೇಲೆ ಭಾರ.", "ಅತ್ಯಂತ ಕರುಣಾಮಯನನ್ನು ಪ್ರೀತಿಸುವ, ನಾಲಿಗೆಯ ಮೇಲೆ ಬೆಳಕು ಮತ್ತು ಮಾಪಕದ ಮೇಲೆ ಭಾರವಾದ (ಅಲ್-ಬುಖಾರೀ ಕೊನೆಯ ಹದೀಸ್)"),
        "dua_ya_dhal_jalal" to DuaText("ಯಾ ಧಲ್-ಜಲಾಲಿ ವಾಲ್-ಇಕ್ರಮ್", "ಓ ಘನತೆ ಮತ್ತು ಗೌರವದ ಒಡೆಯನೇ!", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಸೂಚನೆಯಾದ ದುಆದಲ್ಲಿ ಅದನ್ನು ಹಿಡಿದುಕೊಳ್ಳಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಹೇಳಿದರುಃ'ಯಾ ಧಲ್-ಜಲಾಲಿ ವಾಲ್-ಇಕ್ರಮ್'ಅನ್ನು ಹಿಡಿದುಕೊಳ್ಳಿ."),
        "dua_sleep_wadatu_janbi" to DuaText("ನಿನ್ನ ಹೆಸರಿನಲ್ಲಿ ನಾನು ಮಲಗುತ್ತೇನೆ.", "ನನ್ನ ಒಡೆಯನೇ, ನಿನ್ನ ಹೆಸರಿನಲ್ಲಿ ನಾನು ನನ್ನ ಪಕ್ಷವನ್ನು ಇಡುತ್ತೇನೆ ಮತ್ತು ನಿನ್ನ ಹೆಸರಿನಲ್ಲಿ ನಾನು ಏಳುತ್ತೇನೆ. ನೀನು ನನ್ನ ಪ್ರಾಣವನ್ನು ತೆಗೆದುಕೊಂಡರೆ, ಅದರ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು, ಮತ್ತು ಅದನ್ನು ಬಿಡುಗಡೆ ಮಾಡಿದರೆ, ನಿನ್ನ ನೀತಿವಂತ ಸೇವಕರನ್ನು ರಕ್ಷಿಸುವಂತೆಯೇ ಅದನ್ನು ರಕ್ಷಿಸು.", "ಹಾಸಿಗೆಯನ್ನು ಧೂಳು ಮಾಡಿ ಮಲಗಿದ ನಂತರ.", "ಮಲಗುವ ಮೊದಲು ತನ್ನ ಆತ್ಮವನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುವುದು."),
        "dua_sleep_khalaqta_nafsi" to DuaText("ನೀನು ನನ್ನ ಆತ್ಮವನ್ನು ಸೃಷ್ಟಿಸಿದ್ದೀಯ.", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನನ್ನ ಆತ್ಮವನ್ನು ಸೃಷ್ಟಿಸಿದ್ದೀ ಮತ್ತು ಅದನ್ನು ತೆಗೆದುಕೊಳ್ಳುವೆ. ಅದರ ಮರಣ ಮತ್ತು ಅದರ ಜೀವವು ನಿನಗೆ ಸೇರಿದ್ದು. ನೀನು ಅದನ್ನು ಜೀವಂತವಾಗಿಟ್ಟುಕೊಂಡರೆ ಅದನ್ನು ರಕ್ಷಿಸು. ಮತ್ತು ಅದನ್ನು ಸಾಯುವಂತೆ ಮಾಡಿದಲ್ಲಿ ಅದನ್ನು ಕ್ಷಮಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನನ್ನು ಕ್ಷೇಮಕ್ಕಾಗಿ ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಮಲಗುವ ಮೊದಲು-ಇಬ್ನ್ ಉಮರ್ (ರ.) ವಿವರಿಸಿದ್ದಾನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಮಲಗುವ ಸಮಯದಲ್ಲಿ ಇದನ್ನು ಹೇಳುವಂತೆ ಸೂಚಿಸಿದರು."),
        "dua_sleep_atamana" to DuaText("ಮಲಗುವ ಮೊದಲು ಕೃತಜ್ಞತೆ", "ನಮಗೆ ಆಹಾರ ನೀಡಿದ, ನಮಗೆ ಪಾನೀಯ ನೀಡಿದ, ನಮಗೆ ಸಾಕಾದ ಮತ್ತು ನಮಗೆ ಆಶ್ರಯ ನೀಡಿದ ಅಲ್ಲಾಹನಿಗಾಗಿ ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಇದೆ. ಅವರಿಗೆ ಸಾಕಾಗುವಷ್ಟು ಅಥವಾ ಆಶ್ರಯ ನೀಡುವಷ್ಟು ಯಾರೂ ಇಲ್ಲದ ಎಷ್ಟು ಜನರಿದ್ದಾರೆ.", "ಮಲಗಲು ಹೋದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಮಲಗಲು ಹೋಗುವಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_sleep_rabbas_samawat" to DuaText("ಸ್ವರ್ಗದ ಒಡೆಯ-ನಮ್ಮ ಸಾಲವನ್ನು ತೀರಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ಆಕಾಶಗಳ, ಭೂಮಿಯ ಮತ್ತು ಪ್ರಬಲ ಸಿಂಹಾಸನದ ಒಡೆಯನೇ, ನಮ್ಮ ಒಡೆಯನೇ, ಎಲ್ಲ ವಸ್ತುಗಳ ಒಡೆಯನೇ, ಬೀಜಗಳ ಒಡೆಯನೇ, ಖರ್ಜೂರದ ಕಲ್ಲಿನ ಒಡೆಯನೇ, ತೋರಾ, ಇಂಜಿಲ್ ಮತ್ತು ಫುರ್ಕಾನ್ಗಳ ಒಡೆಯನೇ! ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ. ನೀನು ಮುಂದೋಳವನ್ನು ಹಿಡಿದಿರುವ ಎಲ್ಲದರ ದುಷ್ಟತನದಿಂದ. ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಮೊದಲಿಗನಾಗಿದ್ದೀ, ನಿನ್ನ ಮುಂದೆ ಏನೂ ಇಲ್ಲ. ನೀನು ಕೊನೆಯವನಾಗಿದ್ದೀ, ನಿನ್ನ ನಂತರ ಏನೂ ಇಲ್ಲ. ನೀನು ಸ್ಪಷ್ಟವಾದವನಾಗಿದ್ದೀ, ನಿನ್ನ ಮೇಲೆ ಏನೂ ಇಲ್ಲ. ನೀನು ಗುಪ್ತನಾಗಿದ್ದೀ, ನಿನ್ನಿಂದ ಮರೆಮಾಚಲ್ಪಟ್ಟಿರುವುದು ಏನೂ ಇಲ್ಲ. ನಮಗಾಗಿ ನಮ್ಮ ಸಾಲವನ್ನು ತೀರಿಸು ಮತ್ತು ನಮ್ಮನ್ನು ಬಡತನದಿಂದ ಮುಕ್ತಗೊಳಿಸಿ.", "ಮಲಗುವ ಮೊದಲು, ಬಲಭಾಗದಲ್ಲಿ ಮಲಗಿ-ಫಾತಿಮಾ (ರಾ) ಗೆ ಕಲಿಸಲಾಗುತ್ತದೆ.", "ಸಾಲ ಮತ್ತು ಸಂಕಷ್ಟಗಳಿಂದ ಪರಿಹಾರಕ್ಕಾಗಿ ಒಂದು ದುಆ."),
        "dua_sleep_fear" to DuaText("ನಿದ್ರೆಯಲ್ಲಿ ಭಯ ಅಥವಾ ಅಸ್ವಸ್ಥತೆ", "ನಾನು ಅಲ್ಲಾಹನ ಕೋಪ ಮತ್ತು ಅವನ ಶಿಕ್ಷೆಯಿಂದ, ಅವನ ಸೇವಕರ ದುಷ್ಟತನದಿಂದ, ದೆವ್ವಗಳ ಪಿಸುಗುಟ್ಟಿಯಿಂದ ಮತ್ತು ಅವರು ನನ್ನ ಬಳಿಗೆ ಬರುವುದರಿಂದ ಅವನ ಪರಿಪೂರ್ಣ ಮಾತುಗಳಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ನಿದ್ರೆಯಲ್ಲಿ ಭಯ ಅಥವಾ ಅಸಮಾಧಾನವನ್ನು ಅನುಭವಿಸುವಾಗ.", "ಹಾಗೆ ಮಾಡುವುದರಿಂದ, ಆ ವಿಷಯವು ಅವನಿಗೆ ಹಾನಿಯನ್ನುಂಟು ಮಾಡುವುದಿಲ್ಲ."),
        "dua_waking_afani" to DuaText("ಎಚ್ಚರಃ ಆತನು ನನ್ನ ಆತ್ಮವನ್ನು ಪುನಃಸ್ಥಾಪಿಸಿದನು", "ನನ್ನ ದೇಹಕ್ಕೆ ಕ್ಷೇಮವನ್ನು ನೀಡಿದ, ನನ್ನ ಆತ್ಮವನ್ನು ನನಗೆ ಹಿಂದಿರುಗಿಸಿದ ಮತ್ತು ಆತನನ್ನು ಸ್ಮರಿಸಲು ನನಗೆ ಅವಕಾಶ ನೀಡಿದ ಅಲ್ಲಾಹನಿಗೆ ಎಲ್ಲಾ ಪ್ರಶಂಸೆಗಳು.", "ಎಚ್ಚರಗೊಳ್ಳುವಾಗ.", "ಹೊಸ ಬೆಳಗಿನ ಕೃತಜ್ಞತೆಗಳು."),
        "dua_allahu_rabbi" to DuaText("ಅಲ್ಲಾಹನೇ ನನ್ನ ಒಡೆಯನು.", "ಅಲ್ಲಾಹನೇ, ಅಲ್ಲಾಹನೇ ನನ್ನ ಒಡೆಯನು; ನಾನು ಅವನಿಗೆ ಯಾವುದನ್ನೂ ಸಾಟಿಯಾಗಿ ಸೇರಿಸುವುದಿಲ್ಲ.", "ದುಃಖ ಅಥವಾ ಯಾತನೆಯಲ್ಲಿ-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಇದನ್ನು ಆಸ್ಮಾ ಬಿಂಟ್ ಉಮೈಸ್ (ರ. ಅ.) ಗೆ ಕಲಿಸಿದರು.", "ಸಂಕಷ್ಟದ ಸಮಯದಲ್ಲಿ ತೌಹೀದ್ ಅನ್ನು ಹಿಡಿದುಕೊಳ್ಳಿ."),
        "dua_rahmataka_arju" to DuaText("ನಿನ್ನ ಕರುಣೆಯನ್ನು ನಾನು ನಿರೀಕ್ಷಿಸುತ್ತೇನೆ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನ ಕರುಣೆಯನ್ನು ನಿರೀಕ್ಷಿಸುತ್ತಿದ್ದೇನೆ. ಆದ್ದರಿಂದ ಒಂದು ಕಣ್ಣು ಮಿಟುಕಿಸುವವರೆಗೂ ನನ್ನನ್ನು ನನ್ನ ಮೇಲೆ ಬಿಡುವದಿಲ್ಲ. ನನ್ನ ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳನ್ನು ಸರಿಪಡಿಸಿ. ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ.", "ಸಂಕಷ್ಟದಲ್ಲಿರುವವನ ದುಆ (ದಾವತ್ ಅಲ್-ಮಕ್ರಬ್).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಇದನ್ನು ಸಂಕಟದಲ್ಲಿರುವವನ ದುಆ ಎಂದು ಕರೆದರು."),
        "dua_against_enemy_ahzab" to DuaText("ಶತ್ರುಗಳ ಸೈನ್ಯಗಳ ವಿರುದ್ಧ", "ಓ ಅಲ್ಲಾಹನೇ, ಗ್ರಂಥವನ್ನು ಪ್ರಕಟಿಸುವವನೇ! ಲೆಕ್ಕದಲ್ಲಿ ತ್ವರಿತವಾಗು! ಒಕ್ಕೂಟಗಳನ್ನು ಸೋಲಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ಅವರನ್ನು ಸೋಲಿಸು ಮತ್ತು ಅಲುಗಾಡಿಸು.", "ಶತ್ರುವಿನ ವಿರುದ್ಧ-ಒಕ್ಕೂಟಗಳ ಕದನದ ಡುವಾ.", "ಪ್ರವಾದಿಗಳ ಸಲ್ಲು-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲಾಹ್-ಅಲ್ಲ"),
        "dua_anta_adudi" to DuaText("ನೀನೇ ನನ್ನ ಬೆಂಬಲ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನನ್ನ ಆಶ್ರಯದಾತ ಮತ್ತು ಸಹಾಯಕನಾಗಿದ್ದೀ. ನಿನ್ನ ಮೂಲಕ ನಾನು ಯೋಜನೆ ಹಾಕುತ್ತೇನೆ, ನಿನ್ನ ಮೂಲಕ ನಾನು ಮುನ್ನಡೆಸುತ್ತೇನೆ ಮತ್ತು ನಿನ್ನ ಮೂಲಕ ನಾನು ಹೋರಾಡುತ್ತೇನೆ.", "ಸ್ಪರ್ಧೆ ಅಥವಾ ದೊಡ್ಡ ಸವಾಲಿನ ಮೊದಲು.", "ಇದನ್ನು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಯುದ್ಧದಲ್ಲಿ ಹೇಳಿದರು."),
        "dua_ikfinihim" to DuaText("ಅವರ ವಿರುದ್ಧ ನನಗೆ ಸಾಕು", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಬಯಸಿದರೂ ಅವರ ವಿರುದ್ಧ ನನಗೆ ಸಾಕು.", "ದಬ್ಬಾಳಿಕೆಯ ದುಷ್ಟರಿಗೆ ವಿರುದ್ಧವಾಗಿ-ದಿ ಪೀಪಲ್ ಆಫ್ ದಿ ಡಿಚ್ ಕಥೆಯಲ್ಲಿ ಹುಡುಗನ ದ್ವಂದ್ವ.", "ಅಲ್ಲಾಹು ಆ ಹುಡುಗನನ್ನು ದಬ್ಬಾಳಿಕೆಯಿಂದ ರಕ್ಷಿಸಿದನು."),
        "dua_qadarullah" to DuaText("ಏನಾದರೂ ಕೆಟ್ಟದಾಗಿ ಸಂಭವಿಸಿದಾಗ", "ಇದು ಅಲ್ಲಾಹನ ಆಜ್ಞೆಯಾಗಿದೆ, ಮತ್ತು ಆತನು ತನಗೆ ಇಷ್ಟವಾದದ್ದನ್ನು ಮಾಡಿದನು.", "ಅಹಿತಕರವಾದದ್ದು ಏನಾದರೂ ಸಂಭವಿಸಿದಾಗ,'ಇಫ್ ಓನ್ಲಿ'ಎಂದು ಹೇಳುವ ಬದಲು.", "'ಇಫ್ ಓನ್ಲಿ'ಸೈತಾನ್ಗೆ ಬಾಗಿಲು ತೆರೆಯುತ್ತದೆ."),
        "dua_ala_kulli_hal" to DuaText("ಪ್ರತಿ ಸನ್ನಿವೇಶದಲ್ಲೂ ಪ್ರಶಂಸೆ", "ಎಲ್ಲಾ ಸಂದರ್ಭದಲ್ಲೂ ಅಲ್ಲಾಹನಿಗೇ ಎಲ್ಲ ಸ್ತೋತ್ರಗಳೂ ಇವೆ.", "ಇಷ್ಟವಿಲ್ಲದ ಏನಾದರೂ ಸಂಭವಿಸಿದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ತಮಗೆ ಇಷ್ಟವಿಲ್ಲದ ಯಾವುದನ್ನಾದರೂ ಎದುರಿಸಿದ ನಂತರ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_dogs_barking" to DuaText("ರಾತ್ರಿಯಲ್ಲಿ ನಾಯಿಗಳ ಮೊಳಗಿಸುವಿಕೆ", "ನಾನು ಶಾಪಗ್ರಸ್ತರಾದ ಸೈತಾನ್ನಿಂದ ಅಲ್ಲಾಹನ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ನಾಯಿಗಳು ಬೊಗಳುವುದನ್ನು ಕೇಳಿದಾಗ ಅಥವಾ ಕತ್ತೆಯು ರಾತ್ರಿಯಲ್ಲಿ ಕತ್ತೆ ಹೊಡೆಯುತ್ತದೆ.", "ನೀವು ನೋಡದದ್ದನ್ನು ಅವರು ನೋಡುತ್ತಾರೆ."),
        "dua_leaving_home_adilla" to DuaText("ದಾರಿ ತಪ್ಪಿದ ನಿರಾಶ್ರಿತರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ದಾರಿ ತಪ್ಪದಂತೆ ಅಥವಾ ದಾರಿ ತಪ್ಪದಂತೆ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ, ನಾನು ತಪ್ಪಾಗಿ ವರ್ತಿಸದಂತೆ ಅಥವಾ ಮೂರ್ಖತನದಿಂದ ನಡೆದುಕೊಳ್ಳದಂತೆ ನಾನು ತಪ್ಪಿಸಿಕೊಳ್ಳುತ್ತೇನೆ ಅಥವಾ ತಪ್ಪಿಸಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಮನೆಯಿಂದ ಹೊರಡುವಾಗ-ಉಮ್ ಸಲಮಾ (ರ.) ಅವರು ವಿವರಿಸುತ್ತಾರೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ತಮ್ಮ ಮನೆಯಿಂದ ಹೊರಬಂದಾಗಲೆಲ್ಲಾ ಇದನ್ನು ಪಠಿಸುತ್ತಿದ್ದರು."),
        "dua_ascending_descending" to DuaText("ಮೇಲಕ್ಕೆ ಹೋಗುವುದು ಮತ್ತು ಕೆಳಕ್ಕೆ ಬರುವುದು", "ಅಲ್ಲಾಹ್ (ಮೇಲಕ್ಕೆ ಹೋಗುವಾಗ) ಶ್ರೇಷ್ಠನಾಗಿದ್ದಾನೆ.-ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ.", "ಪ್ರಯಾಣದಲ್ಲಿ, ಮೇಲಕ್ಕೆ ಹೋಗುವಾಗ'ಅಲ್ಲಾಹು ಅಕ್ಬರ್'ಮತ್ತು ಕೆಳಕ್ಕೆ ಬರುವಾಗ'ಸುಭಾನಲ್ಲಾಹ್'ಎಂದು ಹೇಳಿ.", "ಪ್ರಯಾಣ ಮಾಡುವಾಗ ಸಹಚರರ (ಆರ್. ಎ.) ಅಭ್ಯಾಸ."),
        "dua_traveller_sahar" to DuaText("ಬೆಳಗಿನ ಜಾವದ ಮೊದಲು ಪ್ರವಾಸಿಗರ ದುವಾ", "ಒಬ್ಬ ಕೇಳುಗನು ಅಲ್ಲಾಹನನ್ನು ಸ್ತುತಿಸುವುದನ್ನು ಮತ್ತು ಅವನ ಒಳ್ಳೆಯ ಅನುಗ್ರಹಗಳನ್ನು ನಮ್ಮ ಮೇಲೆ ಸಲ್ಲಿಸುವುದನ್ನು ಕೇಳಿದ್ದಾನೆ. ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮೊಂದಿಗೆ ಬಾ ಮತ್ತು ನಮಗೆ ನಿನ್ನ ಅನುಗ್ರಹವನ್ನು ಕರುಣಿಸು-(ನಾನು ಇದನ್ನು ಹೇಳುತ್ತೇನೆ) ಅಲ್ಲಾಹನಲ್ಲಿ ಬೆಂಕಿಯಿಂದ ಆಶ್ರಯ ಪಡೆಯುವುದನ್ನು.", "ಪ್ರಯಾಣದಲ್ಲಿ, ಬೆಳಗಿನ ಜಾವದ ಮೊದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರಯಾಣ ಮಾಡುವಾಗ ಮುಂಜಾನೆ ಈ ಮಾತನ್ನು ಹೇಳಿದರು."),
        "dua_zawwadakallah" to DuaText("ಪ್ರಯಾಣಿಕರಿಗೆಃ ಅಲ್ಲಾಹ್ ತಕ್ವಾ ಒದಗಿಸಲಿ.", "ಅಲ್ಲಾಹ್ ನಿಮ್ಮ ಪ್ರಯಾಣಕ್ಕೆ ತಕ್ವಾವನ್ನು ಒದಗಿಸಲಿ, ನಿಮ್ಮ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸಲಿ ಮತ್ತು ನೀವು ಎಲ್ಲೇ ಇದ್ದರೂ ನಿಮಗೆ ಒಳ್ಳೆಯದನ್ನು ಮಾಡಲಿ.", "ಒಬ್ಬ ಪ್ರಯಾಣಿಕನಿಗೆ ವಿದಾಯ ಹೇಳುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರಯಾಣಕ್ಕೆ ಹೊರಟ ಯಾರಿಗಾದರೂ ಈ ದುಆವನ್ನು ನೀಡಿದರು."),
        "dua_traveller_to_resident" to DuaText("ಹಿಂದೆ ಉಳಿದವರಿಗೆ ಪ್ರಯಾಣಿಕ", "ನಾನು ನಿಮ್ಮನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುತ್ತೇನೆ, ಆತನ ಮೇಲೆ ಎಂದಿಗೂ ನಂಬಿಕೆ ಕಳೆದುಕೊಳ್ಳುವುದಿಲ್ಲ.", "ಕುಟುಂಬಕ್ಕೆ ವಿದಾಯ ಹೇಳಿದಾಗ ಪ್ರಯಾಣಿಕರು ಹೇಳಿದರು.", "ಕುಟುಂಬದ ಸುರಕ್ಷತೆಯನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುವುದು."),
        "dua_entering_village" to DuaText("ಒಂದು ಪಟ್ಟಣ ಅಥವಾ ಗ್ರಾಮವನ್ನು ಪ್ರವೇಶಿಸುವುದು", "ಏಳು ಆಕಾಶಗಳ ಮತ್ತು ಅವುಗಳ ನೆರಳುಗಳ ಒಡೆಯನಾದ ಅಲ್ಲಾಹನೇ, ಏಳು ಭೂಮಿಯ ಒಡೆಯನೇ, ಮತ್ತು ಅವು ಹೊತ್ತುಕೊಳ್ಳುವ ಎಲ್ಲದರ ಒಡೆಯನೇ, ಪಿಶಾಚುಗಳ ಒಡೆಯನೇ, ಮತ್ತು ಅವು ದಾರಿ ತಪ್ಪಿಸುವ ಎಲ್ಲದರ ಒಡೆಯನೇ, ಗಾಳಿಗಳ ಒಡೆಯನೇ, ಮತ್ತು ಅವು ಚದುರಿಸುವ ಎಲ್ಲದರ ಒಡೆಯನೇ! ನಾವು ಈ ಪಟ್ಟಣದ ಒಳಿತಿಗಾಗಿ ಮತ್ತು ಅದರ ಜನರ ಒಳಿತಿಗಾಗಿ ನಿನ್ನನ್ನು ಬೇಡಿಕೊಳ್ಳುತ್ತೇವೆ, ಮತ್ತು ಅದರ ಕೆಡುಕಿನಿಂದ, ಅದರ ಜನರ ಕೆಡುಕಿನಿಂದ ಮತ್ತು ಅದರಲ್ಲಿರುವ ಕೆಡುಕಿನಿಂದ ನಾವು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇವೆ.", "ಒಂದು ಪಟ್ಟಣ ಅಥವಾ ನಗರವನ್ನು ಪ್ರವೇಶಿಸುವ ಮೊದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಪಟ್ಟಣವನ್ನು ಪ್ರವೇಶಿಸಲು ಬಯಸಿದಾಗಲೆಲ್ಲಾ ಇದನ್ನು ಪಠಿಸುತ್ತಿದ್ದರು."),
        "dua_vehicle_stumbles" to DuaText("ವಾಹನವು ಉರುಳಿದಾಗ", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ.", "'ಸೈತಾನ್ ನಾಶವಾಗಲಿ'ಎಂದು ಹೇಳುವ ಬದಲು, ಆ ವಾಹನ ಅಥವಾ ವಾಹನವು ಜಾರಿಬಿದ್ದಾಗ ಅಥವಾ ಎಡವಿಹೋದಾಗ.", "ಬಿಸ್ಮಿಲ್ಲಾಹ್ ಎಂದು ಹೇಳುವುದರಿಂದ ಸೈತಾನನು ನೊಣದ ಗಾತ್ರಕ್ಕೆ ಕುಗ್ಗುತ್ತಾನೆ."),
        "dua_ajz_kasal_haram" to DuaText("ದೌರ್ಬಲ್ಯ ಮತ್ತು ವೃದ್ಧಾಪ್ಯದಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಅಸಹಾಯಕತೆ ಮತ್ತು ಸೋಮಾರಿತನದಿಂದ, ಹೇಡಿತನ ಮತ್ತು ವೃದ್ಧಾಪ್ಯದಿಂದ, ಜೀವನ ಮತ್ತು ಮರಣದ ಪರೀಕ್ಷೆಗಳಿಂದ ಮತ್ತು ಸಮಾಧಿಯ ಶಿಕ್ಷೆಯಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಆಶ್ರಯದ ಸಮಗ್ರ ದೈನಂದಿನ ದುಆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಆಗಾಗ್ಗೆ ಮಾಡಿದ ಒಂದು ದುಆ."),
    )
}
